import * as E from './engine.js';
import * as S from './store.js';
import {MarketAPI,ResearchAPI} from './data.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((n||0)/100),pct=n=>n==null?'—':(n*100).toFixed(1)+'%';
const date=n=>n?new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(n)):'Time unavailable';
const ago=n=>n?Math.max(0,Math.floor((Date.now()-n)/1000))+'s ago':'Not yet verified';
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',games:'<rect x="3" y="4" width="18" height="16" rx="4"/><path d="M7 12h5m-2.5-2.5v5M16 10h.01M18 14h.01"/>',combos:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h5M8 16h8"/>',bets:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2zM8 7h8M8 11h8M8 15h4"/>',goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><path d="m12 12 7-7"/>'};
const icon=key=>`<svg fill="none" stroke="currentColor" stroke-width="1.6" viewBox="0 0 24 24" aria-hidden="true">${icons[key]||icons.goals}</svg>`;
let state,api,research,markets=[],catalog=[],scanController,scanning=false,scanMessage='',scanErrors=[],lastUpdate=0,combos=[],generating=false,syncMessage='',showCount=30;
let scanPromise=null,scanSport=null,loadedSport=null,comboFeedback='';
let filters={sport:'all',window:'180',search:'',lopsided:false,min:.75,max:.88,includeAwaiting:true};let target=3;let route=(location.hash||'#home').slice(1);let draftContext=null,imageFile=null,imageHash=null,imageUrl=null,ocrText='';let timer;
const main=$('#main'),dialog=$('#dialog');
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function modal(title,body){$('#dialog-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!dialog.open)dialog.showModal();}
function heading(title,subtitle,eyebrow='YOUR MARKET WORKSPACE'){return `<section class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><span class="date">${new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'America/Los_Angeles'}).format(new Date())}</span></section>`;}
function empty(title,body,button=''){return `<div class="empty"><div class="empty-icon">◌</div><h3>${title}</h3><p>${body}</p>${button}</div>`;}
function stat(label,value,detail='',cls=''){return `<div class="stat"><p>${label}</p><strong class="${cls}">${value}</strong>${detail?`<small>${detail}</small>`:''}</div>`;}
function nav(){for(const id of ['#side-nav','#bottom-nav'])$(id).innerHTML=Object.entries({home:'Home',games:'Games',combos:'Combos',bets:'My Bets',goals:'Goals'}).map(([key,label])=>`<a href="#${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span></a>`).join('');}
function progress(n,total){return `<div class="progress" role="progressbar" aria-valuenow="${Math.min(100,Math.round(n/total*100))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,n/total*100)}%"></span></div>`;}
function goalList(){return state.goals.map((g,i)=>`<div class="goal-row"><div class="row"><div class="goal-icon">${['⌁','▯','↗'][i]||'◎'}</div><div class="goal-label"><b>${esc(g.name)}</b><p>${money(E.goalSaved(state,g.id))} of ${money(g.target)}</p></div><small>${Math.round(E.goalSaved(state,g.id)/g.target*100)}%</small></div>${progress(E.goalSaved(state,g.id),g.target)}</div>`).join('');}
function paymentCard(){const inc=state.incoming,days=Math.ceil((Date.parse(inc.due)-Date.now())/86400000);return `<div class="payment"><div class="row"><span class="pill ${inc.receivedAt?'good':'warn'}">${inc.receivedAt?'RECEIVED':'INCOMING · NOT RECEIVED'}</span><small>${inc.receivedAt?date(inc.receivedAt):days>0?days+' days away':'Awaiting receipt'}</small></div><div class="row" style="margin-top:12px"><strong>${money(inc.receivedAt?inc.received:inc.expected)}</strong><span class="goal-icon">↙</span></div><p>Expected crypto payment · November 5, 2026<br>Separate from betting funds and profit.</p>${!inc.receivedAt?'<button class="full ghost" data-action="receive">Confirm payment received</button>':'<a href="#goals" class="tiny">Allocate received funds →</a>'}</div>`;}
function home(){const m=E.metrics(state),saved=E.totalSaved(state);return heading('Your edge starts here.','Real markets. Clear decisions. Every dollar accounted for.','EDGEBOARD / OVERVIEW')+`<div class="grid"><section class="card wallet"><div class="wallet-label"><span>Available bankroll</span><span class="pill ${m.deposited?'good':''}">${m.deposited?'CONFIRMED LEDGER':'DEPOSIT UNCONFIRMED'}</span></div><div class="big-number">${money(m.available).replace(/(\.\d{2})$/,'<span>$1</span>')}</div><p class="tiny">${m.deposited?`${money(m.reserved)} reserved in branches · ${m.pending} pending combos`:'$15 starting amount configured. Confirm what you actually deposited.'}</p><div class="wallet-foot"><div><p>Realized net profit / loss</p><strong class="${m.profit<0?'negative':'positive'}">${m.profit>0?'+':''}${money(m.profit)}</strong></div><button class="ghost" data-action="deposit">${m.deposited?'+ Record deposit':'Confirm deposit'}</button></div></section><section class="card build-card"><div><div class="orbit">2—5× <span>YOUR TARGET</span></div><h2>Find your<br>next combo.</h2><p>Explore the next matchups. Compare the evidence. Build a ticket to review.</p></div><button class="primary full" data-action="go-combos">MAKE ME A COMBO <span class="arrow">↗</span></button></section></div><div class="stats">${stat('Gross payouts received',money(m.payouts),'Includes returned stake')}${stat('Active combos',m.pending,'Confirmed wagers only')}${stat('Total amount staked',money(m.staked),'Across all recorded combos')}${stat('Savings set aside',money(saved),`of ${money(state.settings.overallGoal)} overall goal`)}</div>${m.bankroll>=state.settings.cashoutAt?`<div class="notice">Your recorded bankroll reached ${money(state.settings.cashoutAt)}. Consider withdrawing ${money(state.settings.cashoutAmount)} into savings. Record it only after completing the transfer.</div>`:''}<div class="grid"><section><div class="section-title"><h2>Coming up next</h2><a href="#games">All games ↗</a></div><div id="home-markets">${homeMarkets()}</div></section><section class="stack"><div class="card"><div class="card-head"><h2>Make it count.</h2><a href="#goals" class="tiny">Your goals ↗</a></div>${goalList()}<small>Only confirmed savings count toward progress.</small></div>${paymentCard()}</section></div>`;}
function homeMarkets(){const list=E.filteredMarkets(markets,{window:'180'}).filter(m=>m.supported).slice(0,3);return list.length?`<div class="stack">${list.map(marketCard).join('')}</div>`:empty(scanning?'Finding upcoming matches…':scanErrors.length?'Market connection needs attention':'No matches in the next 3 hours',scanning?'Loading real Polymarket US events progressively.':scanErrors.length?esc(scanErrors[0]):'Try a wider time window in Games. No sample games are shown.','<button data-action="go-games">Browse games</button>');}
function timeOptions(){return [['live','Live · open markets'],['15','Next 15 minutes'],['30','Next 30 minutes'],['60','Next 1 hour'],['180','Next 3 hours'],['360','Next 6 hours'],['720','Next 12 hours'],['1440','Next 24 hours'],['all','All upcoming']].map(([v,l])=>`<option value="${v}" ${filters.window===v?'selected':''}>${l}</option>`).join('');}
function filterUI(){return `<div class="filters"><label>Search competitors<input id="search" ${generating?'disabled':''} placeholder="Player or team name" value="${esc(filters.search)}"></label><label>Sport<select id="sport" ${generating?'disabled':''}><option value="all">All sports</option>${catalog.map(s=>`<option value="${esc(s.slug)}" ${s.slug===filters.sport?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Starts in · Pacific Time<select id="window" ${generating?'disabled':''}>${timeOptions()}</select></label></div><label class="check"><input id="include-awaiting" type="checkbox" ${filters.includeAwaiting?'checked':''} ${generating?'disabled':''}>Also show open matches awaiting start</label><p class="hint">Awaiting-start matches have a past scheduled time, but the feed has not marked them live or ended. Their original time stays visible; it is not a new start-time estimate.</p>`;}
function statusLine(){return `<div class="status-line"><span>${scanning?'◌ '+esc(scanMessage||'Connecting…'):'● '+(lastUpdate?'Last successful scan '+date(lastUpdate):'Connecting to Polymarket US')}</span><span>${markets.length} markets loaded · US venue only</span></div>${scanErrors.length?`<div class="notice">${scanErrors.map(esc).join('<br>')}</div>`:''}`;}
function marketCard(m){const waiting=E.awaitingStart(m);const t=m.live?'LIVE':waiting?'AWAITING START · '+date(m.start):m.start?date(m.start):'Time unavailable';return `<article class="card market"><div class="market-top"><span>${esc(m.sportName)} · ${esc(m.league)}</span><span class="${m.live?'positive':''}">${esc(t)}</span></div><h3>${esc(m.title)}</h3>${m.outcomes.slice(0,3).map(o=>`<div class="outcome"><span class="name">${esc(o.name)} ${o.name===m.favorite?.name?'<small>↗ favorite</small>':''}</span><span class="price ${o.name===m.favorite?.name?'fav':''}">${o.quote?Math.round(o.quote*100)+'¢':'—'}</span><span class="odds">${o.quote?(1/o.quote).toFixed(2)+'×':'—'}</span></div>`).join('')}<div class="market-meta"><span>${m.spread===null?'Spread unavailable':(m.spread*100).toFixed(1)+'¢ spread'}</span><span data-countdown="${m.start||''}" data-live="${m.live||waiting}">${m.live?'Live':waiting?'Start not confirmed by feed':countdown(m.start)}</span></div><div class="badge-row"><span class="pill">${m.supported?'Match winner':'Browse only · '+esc(m.type)}</span><span class="pill ${m.research?.available?'good':''}">${m.research?.available?'Limited research':'Research unavailable'}</span></div><div class="market-meta"><span>Buy quotes · not independent probabilities</span><span>${m.verifiedAt?ago(m.verifiedAt):'Book not verified'}</span></div><div class="market-actions"><button data-action="research" data-id="${esc(m.id)}">Research & details</button><a href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Polymarket ↗</a></div></article>`;}
function countdown(start){if(!start)return 'Start unknown';const mins=Math.ceil((start-Date.now())/60000);return mins<=0?'Scheduled start passed':mins<60?`Starts in ${mins}m`:`Starts in ${Math.floor(mins/60)}h ${mins%60}m`;}
function games(){return heading('The games board.','Browse live US quotes. Start times automatically use Pacific Time.','MARKET DISCOVERY')+filterUI()+`<div class="row"><label class="check"><input id="lopsided" type="checkbox" ${filters.lopsided?'checked':''}>Lopsided favorites only (${Math.round(filters.min*100)}–${Math.round(filters.max*100)}%)</label><button data-action="refresh">${scanning?'Restart scan':'↻ Refresh'}</button></div><div id="market-status">${statusLine()}</div><div id="games-list">${gameList()}</div>`;}
function gameList(){const list=E.filteredMarkets(markets,filters);if(!list.length)return empty(scanning?'Scanning the schedule…':'No matching open games',scanErrors.length?'Some data requests failed. Review the connection messages above.':'No matches satisfy these filters. Live games use the Live filter; open matches with elapsed schedules appear when awaiting-start matches are enabled.');
 const visible=list.slice(0,showCount),scheduled=visible.filter(m=>!E.awaitingStart(m)),waiting=visible.filter(m=>E.awaitingStart(m));
 return `${scheduled.length?`<div class="market-grid">${scheduled.map(marketCard).join('')}</div>`:''}${waiting.length?`<div class="section-title"><h2>Awaiting start · schedule elapsed</h2><span class="pill">${waiting.length} SHOWN</span></div><p class="hint">Still open and not marked live in the feed. These are separate from games confirmed to start within your selected window.</p><div class="market-grid">${waiting.map(marketCard).join('')}</div>`:''}${list.length>showCount?'<div class="actions"><button data-action="more">Show more matches</button></div>':''}`;}
function comboPage(){const stake=state.settings.stake,m=E.metrics(state);return heading('One ticket. Your call.','Choose a target, review the evidence, then place it yourself.','COMBO BUILDER')+`<section class="card">${filterUI()}<div class="target-grid">${[2,3,4,5].map(n=>`<button class="target ${n===target?'selected':''}" data-action="target" ${generating?'disabled':''} data-target="${n}" aria-pressed="${n===target}"><strong>${n}×</strong><span>${{2:'Lower target',3:'Balanced target',4:'Higher target',5:'Higher target'}[n]}</span></button>`).join('')}</div><div class="settings-grid"><label>Illustrative stake ($)<input id="combo-stake" type="number" min="0.01" step="0.01" value="${stake/100}"></label><label>Staking mode<select id="staking-mode"><option value="flat">Flat stake</option><option value="branch">Branching · configure below</option></select></label></div>${stake>m.bankroll*state.settings.riskPercent/100?`<div class="notice">${money(stake)} exceeds ${state.settings.riskPercent}% of your confirmed bankroll. This is a preview; no wager will be placed.</div>`:''}<details><summary>Evidence & market filters</summary><div class="settings-grid"><label>Maximum legs<select id="max-legs">${[2,3,4,5,6].map(n=>`<option ${n===state.settings.maxLegs?'selected':''}>${n}</option>`).join('')}</select></label><label>Maximum bid/ask spread (¢)<input id="max-spread" type="number" min="0" max="50" step="1" value="${state.settings.maxSpread*100}"></label><label>Minimum book depth (shares)<input id="min-depth" type="number" min="0" value="${state.settings.minDepth}"></label></div><label class="check"><input id="require-research" type="checkbox" ${state.settings.requireResearch?'checked':''}>Require independently supported research</label><p class="hint">The free team feed offers limited history; no validated prediction model is connected. Requiring independent support can correctly return no eligible combos.</p></details><button class="primary full" data-action="generate" ${generating?'disabled':''}>${generating?'VERIFYING QUOTES & RESEARCH…':'GENERATE MY COMBO'} <span class="arrow">↗</span></button><p class="form-note">Estimates only. Native Combo eligibility and actual payout must be confirmed on Polymarket. Higher targets can lose the entire stake.</p></section><div id="market-status">${statusLine()}</div><div id="combo-results">${comboResults()}</div><section class="section"><div class="section-title"><h2>Saved drafts</h2><span class="pill">NOT WAGERS</span></div>${state.combos.length?state.combos.slice().reverse().slice(0,10).map(comboCard).join(''):empty('Your shortlist starts here.','Save a generated combo, then return after you have placed your actual wager.')}</section><section class="section">${branchPanel()}</section>`;}
function comboResults(){return (comboFeedback?`<div class="notice info">${comboFeedback}</div>`:'')+(combos.length?combos.map(comboCard).join(''):empty('Ready when you are.','Generate candidates from freshly checked quotes. If no supported combination meets the target, the app will say so.'));}
function comboCard(c){const stake=state.settings.stake,expired=c.legs.some(l=>Date.now()-(l.verifiedAt||0)>90000);return `<article class="card combo"><div class="row"><div><div class="eyebrow">${c.placed?'PLACED FROM DRAFT':'CANDIDATE COMBO'} · ${c.legs.length} LEGS</div><h3>${c.target}× target</h3></div><div class="combo-mult">≈${c.multiplier.toFixed(2)}×</div></div>${c.targetMatched===false?`<div class="notice">Closest available reference: ${c.multiplier.toFixed(2)}×. This is outside the ±15% range for your ${c.target}× target. No filters were relaxed; check whether this different payout suits you.</div>`:''}${c.legs.map((l,i)=>`<div class="leg"><div class="leg-num">${i+1}</div><div class="leg-body"><b>${esc(l.selection)}</b><p>${esc(l.title)}</p><small>${esc(l.sportName)} · ${date(l.start)}${E.awaitingStart(l)?' · awaiting start; schedule elapsed':''} · market favorite</small><small>${l.research?.available?'Limited research; no validated lean':'Research unavailable · market-only selection'}</small><a class="tiny" href="${esc(l.url)}" target="_blank" rel="noopener">Market ↗</a></div><span class="leg-odds">${(1/l.quote).toFixed(2)}×</span></div>`).join('')}<div class="combo-summary"><div><small>Illustrative stake</small><strong>${money(stake)}</strong></div><div><small>Estimated gross</small><strong>${money(Math.round(stake*c.multiplier))}</strong></div><div><small>Estimated profit</small><strong class="positive">${money(Math.round(stake*c.multiplier)-stake)}</strong></div></div><p class="tiny">Market-implied hit approximation: ${pct(c.implied)} assuming independence. This is not a modeled chance of winning. Shared competitors/events are excluded; other correlations may remain. Fees and the native Combo quote can change payout.</p><div class="badge-row"><span class="pill ${expired?'warn':'good'}">${expired?'QUOTE SNAPSHOT · REFRESH BEFORE USE':'RECENT US QUOTES'}</span><span class="pill">LEG ELIGIBILITY CHECKED · TICKET UNVERIFIED</span></div><p class="hint">Snapshot ${date(c.at)}</p><div class="actions"><button data-action="copy-combo" data-id="${c.id}">Copy combo</button><a href="https://polymarket.us/" target="_blank" rel="noopener">Open Polymarket ↗</a><button data-action="save-combo" data-id="${c.id}">Save draft</button></div><div class="actions"><button class="ghost" data-action="combo-research" data-id="${c.id}">Research each leg</button><button class="primary" data-action="log-combo" data-id="${c.id}">I placed this · record bet</button><button class="ghost" data-action="decline" data-id="${c.id}">Decline</button></div></article>`;}
function branchPanel(){return `<div class="card"><div class="card-head"><div><h2>Branching funds</h2><p>Reserve received money. Allocate each branch once.</p></div><button data-action="start-branch">+ $1 root</button></div>${state.branches.length?state.branches.map(b=>`<div class="branch" style="--level:${b.level-1}"><div class="row"><b>Branch ${esc(b.id.slice(0,6))} · L${b.level}</b><span class="pill">${esc(b.status)}</span></div><p>Stake ${money(b.stake)} · Received ${money(b.payout)} · Carried ${money(b.carried||0)} · Remaining ${money(Math.max(0,b.payout-(b.carried||0)))}</p><p>${b.parent?'Parent '+esc(b.parent.slice(0,6)):'Root reservation'}</p>${['won','cashed-out','voided'].includes(b.status)&&b.payout>0&&!b.split?`<button data-action="split" data-id="${b.id}">Allocate child branches</button>`:''}${b.status==='ready'?`<button data-action="release" data-id="${b.id}">Release reservation</button>`:''}</div>`).join(''):empty('A tree built on received funds.','Start with a $1 reservation after confirming your deposit. Attach a recorded wager to the branch. Only received payouts can fund its children.')}</div>`;}
function betCard(b){const result=E.betResult(b),pending=result==='pending',net=b.payout-b.stake;return `<article class="bet-row ticket ${pending?'ticket-pending':''}"><div class="row"><div><h3>${esc(b.legs.map(l=>l.selection).join(' + '))}</h3><p>${date(b.placedAt)} · ${b.legs.length} legs · ${b.multiplier.toFixed(2)}×</p></div><span class="pill ${pending?'warn':result==='won'?'good':result==='lost'?'bad':''}">${pending?'PENDING':result==='break-even'?'BREAK EVEN':result==='won'?'WIN':'LOSS'}${b.status==='cashed-out'?' · CASH-OUT':''}</span></div><div class="ticket-amounts"><div><small>Stake</small><strong>${money(b.stake)}</strong></div><div><small>${pending?'Potential gross payout':'Received payout'}</small><strong>${money(pending?b.potential:b.payout)}</strong></div><div><small>${pending?'Result':'Net profit / loss'}</small><strong class="${pending?'neutral':net>0?'positive':net<0?'negative':'neutral'}">${pending?'Awaiting':(net>0?'+':'')+money(net)}</strong></div></div>${b.resolution&&pending?`<div class="notice info">Public estimate: ${money(b.resolution.payout)}. Confirm the actual received payout below.</div>`:''}<div class="actions">${pending?`<button class="primary" data-action="settle" data-id="${b.id}">Record result / cash-out</button><button data-action="correct-bet" data-id="${b.id}">Correct ticket</button><button data-action="check-bet" data-id="${b.id}">Check results</button>`:''}<button data-action="bet-image" data-id="${b.id}">${b.screenshotHash?'View screenshot':'Attach screenshot'}</button></div></article>`;}
function breakdown(key){const groups=new Map();for(const b of state.bets.filter(b=>b.status!=='pending')){const name=key==='sport'?[...new Set(b.legs.map(l=>l.sportName||l.sport||'Unspecified'))].join(' / '):key==='target'?(b.target?b.target+'×':'Manual'):b.legs.length+' legs';const a=groups.get(name)||{n:0,w:0,p:0};a.n++;a.w+=E.betResult(b)==='won'?1:0;a.p+=b.payout-b.stake;groups.set(name,a);}return `<div class="table-scroll"><table><thead><tr><th>${key==='sport'?'Sport':key==='target'?'Target':'Leg count'}</th><th>Settled</th><th>Win rate*</th><th>P/L</th></tr></thead><tbody>${[...groups].map(([k,a])=>`<tr><td>${esc(k)}</td><td>${a.n}</td><td>${pct(a.w/a.n)}<div class="mini-bar"><i style="width:${a.w/a.n*100}%"></i></div></td><td>${money(a.p)}</td></tr>`).join('')||'<tr><td colspan="4">No settled wagers yet.</td></tr>'}</tbody></table></div>`;}
function bankrollChart(){if(!state.cash.length&&!state.bets.length)return '<div class="plot-empty">Your bankroll history appears after a confirmed deposit.</div>';const events=[...state.cash.map(x=>({at:x.at,value:x.kind==='deposit'?x.amount:-x.amount})),...state.bets.flatMap(b=>[{at:b.placedAt,value:-b.stake},...(b.status!=='pending'?[{at:b.settledAt,value:b.payout}]:[])])].sort((a,b)=>a.at.localeCompare(b.at));let sum=0;const values=[0,...events.map(e=>(sum+=e.value))],max=Math.max(100,...values),min=Math.min(0,...values),points=values.map((v,i)=>`${i/(values.length-1)*600},${115-(v-min)/(max-min)*100}`).join(' ');return `<svg class="chart" viewBox="0 0 600 130" preserveAspectRatio="none" role="img" aria-label="Confirmed bankroll timeline, ending at ${money(sum)}"><path d="M0 115H600" stroke="#344133"/><polyline points="${points}" fill="none" stroke="var(--green)" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="chart-labels"><span>${date(events[0].at)}</span><span>${money(sum)} latest</span></div>`;}
function periodPL(weekly=false){const group=new Map();for(const b of state.bets.filter(b=>b.status!=='pending')){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles'}).format(new Date(b.settledAt));let key=day;if(weekly){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));key=d.toISOString().slice(0,10);}group.set(key,(group.get(key)||0)+b.payout-b.stake);}return [...group].sort(([a],[b])=>b.localeCompare(a)).slice(0,14).map(([d,n])=>`<div class="row" style="padding:8px 0"><small>${esc(d)}</small><b class="${n<0?'negative':'positive'}">${money(n)}</b></div><div class="mini-bar"><i style="width:${Math.abs(n)/Math.max(1,...[...group.values()].map(Math.abs))*100}%;background:${n<0?'var(--red)':'var(--green)'}"></i></div>`).join('')||'<p class="hint">No realized results yet.</p>';}
function bets(){const m=E.metrics(state),w=E.latestWalletSnapshot(state),gap=w?w.available-m.bankroll:0;return heading('Every ticket. Every dollar.','A ledger of wagers you confirm—not a record of suggestions.','MY BETS')+`<div class="actions"><button class="primary" data-action="upload">↑ Upload bet screenshot</button><button data-action="manual">+ Enter combo manually</button><button data-action="sync">Sync now ${state.outbox.length?'· queued':''}</button></div><p class="hint" id="sync-status">${esc(syncMessage|| (state.syncAt?'Last confirmed sync '+date(state.syncAt):'Google Sheets is not connected. Local records are saved on this device.'))}</p><section class="card ledger-summary"><div class="card-head"><h2>Balance breakdown</h2><div class="actions"><button data-action="wallet-snapshot">Check against Polymarket</button><button data-action="correct-deposit">Correct initial deposit</button></div></div>${w?`<div class="wallet-check"><div><small>POLYMARKET SNAPSHOT · ${date(w.at)}</small><strong>${money(w.total)} total</strong><p>${money(w.available)} available · ${money(w.positions)} open positions</p></div><span class="pill ${Math.abs(gap)<=2?'good':'warn'}">${Math.abs(gap)<=2?'MATCHED':`${gap>0?'+':''}${money(gap)} CASH GAP`}</span></div>`:'<div class="notice info">Add a Polymarket wallet snapshot to compare live available cash with the ticket ledger without treating the difference as profit.</div>'}<div class="ticket-amounts"><div><small>Ledger available cash</small><strong>${money(m.bankroll)}</strong></div><div><small>Pending stakes</small><strong>${money(m.pendingStake)}</strong></div><div><small>Realized profit / loss</small><strong class="${m.profit<0?'negative':'positive'}">${money(m.profit)}</strong></div></div><p class="hint">Deposits ${money(m.deposited)} − withdrawals ${money(m.withdrawn)} + realized P/L ${money(m.profit)} − pending stakes ${money(m.pendingStake)} = ${money(m.bankroll)}. The snapshot is a checkpoint; only individual tickets and transfers change calculated profit.</p>${w&&Math.abs(gap)>2?`<p class="notice">The ledger is missing ${gap>0?'net incoming ticket proceeds or a deposit':'a purchase, withdrawal, fee or other outgoing record'} totaling ${money(Math.abs(gap))}. Review the history around this snapshot.</p>`:''}</section><div class="stats">${stat('Realized net P/L',money(m.profit),'Settled payouts minus settled stakes',m.profit<0?'negative':'positive')}${stat('ROI',pct(m.roi),'On settled stakes')}${stat('Win rate',pct(m.winRate),'Profitable / (profitable + losing tickets)')}${stat('Received payouts',money(m.payouts),'Includes returned stake')}</div><div class="grid"><section class="card"><div class="card-head"><h2>Pending first</h2><span class="pill">${state.bets.length} RECORDED</span></div><h3>Pending · ${m.pending}</h3><p class="hint">${money(m.pendingStake)} staked · potential payouts are not available cash.</p>${state.bets.filter(b=>b.status==='pending').slice().reverse().map(betCard).join('')||'<p class="hint">No pending tickets.</p>'}<h3 class="settled-heading">Settled · ${state.bets.length-m.pending}</h3>${state.bets.filter(b=>b.status!=='pending').sort((a,b)=>b.settledAt.localeCompare(a.settledAt)).map(betCard).join('')||'<p class="hint">No settled tickets yet.</p>'}</section><section class="card"><h2>Performance</h2>${bankrollChart()}<div class="metric-list">${[['Pending',m.pending],['Won',m.won],['Lost',m.lost],['Cashed out',m.cashedOut],['Realized losses',money(m.losses)],['Total staked',money(m.staked)],['Current streak',Math.abs(m.run)+(m.run<0?' losses':' wins')],['Best win streak',m.bestWin],['Longest loss streak',m.bestLoss],['Average accepted odds',state.bets.length?(state.bets.reduce((a,b)=>a+b.multiplier,0)/state.bets.length).toFixed(2)+'×':'—']].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div><details><summary>Daily realized P/L · Pacific Time</summary>${periodPL()}</details><details><summary>Weekly realized P/L · week of Monday</summary>${periodPL(true)}</details><details><summary>Performance by sport, target & leg count</summary>${breakdown('sport')}${breakdown('target')}${breakdown('legs')}<p class="hint">*Breakdown rates include all settled tickets, including cash-outs and voids. Multisport combos are their own category.</p></details></section></div><div class="actions"><button data-action="export">Export JSON backup</button><button data-action="csv">Export wagers CSV</button><button data-action="import">Restore JSON backup</button></div>`;}
function goals(){const saved=E.totalSaved(state),available=state.incoming.received-state.transfers.filter(t=>t.source==='incoming').reduce((a,b)=>a+b.amount,0);return heading('Turn progress into plans.','Your savings are real money set aside. Potential payouts never count.','SAVINGS & TRANSFERS')+`<div class="card"><div class="row"><div><p class="eyebrow">OVERALL ASPIRATIONAL TARGET</p><h1>${money(saved)} <small>of ${money(state.settings.overallGoal)}</small></h1></div><span class="goal-icon">↗</span></div>${progress(saved,state.settings.overallGoal)}<p class="hint">Immediate goals total ${money(state.goals.reduce((a,b)=>a+b.target,0))}. This target is not an expected gambling return.</p></div><section class="section grid"><div class="stack">${state.goals.map(g=>`<article class="card"><div class="row"><h2>${esc(g.name)}</h2><button class="ghost" data-action="edit-goal" data-id="${g.id}">Edit</button></div><p style="margin-top:15px">${money(E.goalSaved(state,g.id))} saved / ${money(g.target)}</p>${progress(E.goalSaved(state,g.id),g.target)}<button class="full ghost" style="margin-top:20px" data-action="allocate" data-id="${g.id}">Record contribution</button></article>`).join('')}</div><div class="stack"><div class="card"><h2>Incoming payment</h2><p class="hint">Expected November 5, 2026 · confirm actual receipt.</p>${paymentCard()}${state.incoming.receivedAt?`<p class="hint">Unallocated received funds: ${money(available)}</p>`:''}</div><div class="card"><h2>Transfer history</h2>${state.transfers.length?state.transfers.slice().reverse().map(t=>`<div class="bet-row"><div class="row"><b>${esc(t.kind==='incoming'?'Crypto payment received':state.goals.find(g=>g.id===t.goalId)?.name||'Contribution')}</b><span>${money(t.amount)}</span></div><small>${date(t.at)} · ${esc(t.source||'External payment')}</small></div>`).join(''):'<p class="hint">No received payments or savings contributions yet.</p>'}</div></div></section>`;}
function render(){nav();main.innerHTML=({home,games,combos:comboPage,bets,goals}[route]||home)();}
async function mutate(fn){const saved=await S.commit(fn);state=saved.state;render();void S.sync(state,updateSync);return saved.result;}
function updateSync(text){syncMessage=text;if($('#sync-status'))$('#sync-status').textContent=text;}
function updateMarketViews(){if($('#market-status'))$('#market-status').innerHTML=statusLine();if($('#games-list'))$('#games-list').innerHTML=gameList();if($('#home-markets'))$('#home-markets').innerHTML=homeMarkets();if(!generating&&$('#combo-results'))$('#combo-results').innerHTML=comboResults();}
function scan({sport=filters.sport,force=false}={}){
 if(scanning&&scanSport===sport&&!force)return scanPromise;
 scanController?.abort();const controller=new AbortController();scanController=controller;scanSport=sport;scanning=true;scanErrors=[];
 const fresh=new Map();scanMessage='Discovering sports…';updateMarketViews();
 const run=(async()=>{try{
  if(!catalog.length){catalog=await api.catalog(controller.signal);if(controller.signal.aborted)return;if(['games','combos'].includes(route))render();}
  const result=await api.scan({sport,maxPages:state.settings.maxPages,signal:controller.signal,onPage:rows=>{if(controller.signal.aborted||scanController!==controller)return;for(const m of rows)fresh.set(m.id,m);markets=[...fresh.values()];updateMarketViews();},onProgress:msg=>{if(controller.signal.aborted)return;scanMessage=msg;updateMarketViews();}});
  if(controller.signal.aborted)return;
  scanErrors=[...result.errors,...(result.truncated.length?['Scan limit reached for '+result.truncated.join(', ')+'. Increase page limit in Settings; coverage is incomplete.']:[])];
  if(result.total||!result.errors.length){markets=[...fresh.values()];loadedSport=sport;lastUpdate=Date.now();await S.write('cache','markets',{at:lastUpdate,markets,catalog,sport});}
  notifyNewMarkets();
 }catch(e){if(!controller.signal.aborted)scanErrors=[e.message];}
 finally{if(scanController===controller){scanning=false;scanPromise=null;updateMarketViews();}}})();
 scanPromise=run;return run;
}
function diagnosticText(d){return Object.entries(d.rejected).map(([reason,count])=>`${count}: ${reason}`).join('; ');}
async function generate(){
 if(generating)return;
 state.settings.stake=E.cents($('#combo-stake').value);state.settings.maxLegs=Number($('#max-legs').value);state.settings.maxSpread=Number($('#max-spread').value)/100;state.settings.minDepth=Number($('#min-depth').value);state.settings.requireResearch=$('#require-research').checked;
 if(state.settings.stake<=0)throw new Error('Enter a positive illustrative stake.');
 filters.search=$('#search')?.value||filters.search;
 const requested={...filters},requestedTarget=target;
 await S.save(state);generating=true;combos=[];comboFeedback='';render();
 try{
  // Await the selected sport's scan; never generate from an old sport or an
  // unfinished first page while later pages contain the upcoming matches.
  if(scanning||loadedSport!==requested.sport||!lastUpdate||Date.now()-lastUpdate>60000)await scan({sport:requested.sport});
  const visible=E.filteredMarkets(markets,requested),pool=visible.filter(m=>m.supported&&m.comboEnabled).slice(0,40);
  if(pool.length<2)throw new Error(`${visible.length} matching open markets; ${pool.length} supported native-combo legs. At least two different events are needed. ${scanErrors.length?'Coverage is incomplete: '+scanErrors.join(' '):'Try Live, enable awaiting-start matches, or choose a longer window.'}`);
  await api.verify(pool);
  const before=E.comboDiagnostics(pool,{...state.settings,requireResearch:false});
  const candidates=before.eligible;
  // Attempt research for every candidate searched, not just the first 12.
  let next=0;await Promise.all(Array.from({length:Math.min(2,candidates.length)},async()=>{while(next<candidates.length){const m=candidates[next++];m.research=await research.research(m);}}));
  if(candidates.some(m=>Date.now()-m.verifiedAt>45000))await api.verify(candidates);
  const diagnostics=E.comboDiagnostics(pool,state.settings);
  if(diagnostics.eligible.length<2)throw new Error(`${pool.length} markets checked; ${diagnostics.eligible.length} usable legs. ${diagnosticText(diagnostics)}`);
  combos=E.buildCombos(candidates,requestedTarget,{...state.settings,allowNearest:true});
  if(!combos.length)throw new Error(`${diagnostics.eligible.length} usable legs, but no compatible combination: events or competitors overlap. No correlation rules were relaxed.`);
  const waiting=candidates.filter(m=>E.awaitingStart(m)).length;
  comboFeedback=esc(`${visible.length} matching markets · ${pool.length} checked · ${diagnostics.eligible.length} usable legs${waiting?' · '+waiting+' awaiting start':''}. ${diagnosticText(diagnostics)}${scanErrors.length?' Partial scan: '+scanErrors.join(' '):''}`);
  toast(combos[0].targetMatched?`${combos.length} candidate drafts. Review the native quote.`:'No close target match; showing clearly labeled nearest alternatives.');
 }catch(e){comboFeedback=esc(e.message);toast(e.message);}
 finally{generating=false;render();}
}
function formValue(form,name){return new FormData(form).get(name);}
function numberField(label,name,value,extra=''){return `<label>${label}<input type="number" name="${name}" required step="0.01" min="0.01" value="${value}" ${extra}></label>`;}
function errorBox(){return '<p class="form-error" id="form-error" role="alert"></p>';}
function depositDialog(){modal('Confirm an actual deposit',`<p class="hint">This only updates your personal ledger. It does not transfer money.</p><form id="deposit-form">${numberField('Amount actually deposited ($)','amount',E.metrics(state).deposited?'':'15')}<label class="check"><input name="confirmed" type="checkbox" required>I confirm this money is in my Polymarket wallet.</label>${errorBox()}<button class="primary full">Confirm deposit</button></form>`);}
function settingsDialog(){modal('Your workspace settings',`<form id="settings-form"><div class="settings-grid">${numberField('Default stake ($)','stake',state.settings.stake/100)}${numberField('Bankroll risk reminder (%)','risk',state.settings.riskPercent,'max="100"')}${numberField('Daily loss reminder ($)','loss',state.settings.dailyLoss/100)}${numberField('Low balance reminder ($)','low',state.settings.lowBalance/100)}${numberField('Cash-out reminder threshold ($)','cashout',state.settings.cashoutAt/100)}${numberField('Suggested withdrawal ($)','withdraw',state.settings.cashoutAmount/100)}${numberField('Overall savings target ($)','overall',state.settings.overallGoal/100)}<label>Max pages per sport<input name="pages" type="number" min="1" max="100" value="${state.settings.maxPages}"></label><label>Lopsided minimum (%)<input name="favmin" type="number" min="50" max="99" value="${filters.min*100}"></label><label>Lopsided maximum (%)<input name="favmax" type="number" min="50" max="99" value="${filters.max*100}"></label></div><details><summary>Google Sheets & optional proxy</summary><p class="hint">Deploy the included Worker and Apps Script using the <a href="./SETUP.md" target="_blank">setup guide ↗</a>. Never put private keys in GitHub.</p><label>Worker URL<input name="proxy" type="url" placeholder="https://your-worker.workers.dev" value="${esc(state.settings.proxy)}"></label><label>Sync passphrase (this session only)<input name="token" type="password" autocomplete="off" placeholder="Worker APP_TOKEN"></label><p class="hint">Sheets receives your confirmed ledger and combo history. Screenshots stay local. Queued changes: ${state.outbox.length}.</p></details><details><summary>Notifications & iPhone installation</summary><button type="button" data-action="notifications">Enable notifications while open</button><p class="hint">On iPhone: Safari → Share → Add to Home Screen. Background push needs a backend and push subscription; this static app only checks reminders while open. Telegram: see the setup guide.</p></details>${errorBox()}<button class="primary full" style="margin-top:15px">Save settings</button></form>`);}
function beginBet(combo=null){draftContext=combo;imageFile=null;imageHash=null;ocrText='';if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=null;betDialog();}
function betDialog(values={}){const c=draftContext;modal('Confirm your actual combo',`<p class="hint">Check every field against your accepted Polymarket ticket. OCR is a draft only. No wager is saved until you confirm.</p><label>Bet screenshot (PNG, JPEG, WebP · up to 12 MB)<input id="bet-file" type="file" accept="image/png,image/jpeg,image/webp"></label>${imageUrl?`<img class="preview-image" src="${imageUrl}" alt="Your selected wager screenshot">`:''}<div id="ocr-status" class="hint">${ocrText?'Text extracted. Review selections and amounts below.':'Optional: choose an image to run local OCR. Image pixels are not uploaded.'}</div><form id="bet-form"><label>Ticket ID (optional, prevents duplicates)<input name="ticketId" value="${esc(values.ticketId||'')}"></label><label>Selected competitors · one per line<textarea name="selections" required rows="${Math.max(3,c?.legs.length||3)}" placeholder="Selected player or team 1\nSelected player or team 2">${esc(values.selections||c?.legs.map(l=>l.selection).join('\n')||'')}</textarea></label><label>Sport for manual entries<input name="sport" value="${esc(values.sport||'')}" placeholder="e.g. Tennis or NBA"></label><div class="settings-grid">${numberField('Actual stake ($)','stake',values.stake??'')}${numberField('Accepted multiplier','multiplier',values.multiplier??'')}${numberField('Accepted potential gross payout ($)','potential',values.potential??'')}<label>Date/time placed · your device timezone<input name="placedAt" type="datetime-local" required value="${values.placedAt||localDateTime()}"></label></div><label>Use a reserved branch<select name="branchId"><option value="">Flat staking</option>${state.branches.filter(b=>b.status==='ready').map(b=>`<option value="${b.id}">${esc(b.id.slice(0,6))} · ${money(b.stake)} · Level ${b.level}</option>`).join('')}</select></label><details ${ocrText?'open':''}><summary>Extracted text · verify, don't assume</summary><textarea class="ocr-output" readonly>${esc(ocrText)}</textarea><p class="hint">Selection names, dates and market IDs require your review. To record a later result screenshot, use an existing wager's settlement button.</p></details><label class="check"><input name="confirm" type="checkbox" required>I placed this combo and verified its accepted details.</label>${errorBox()}<button class="primary full">CONFIRM BET</button></form>`);}
function localDateTime(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
async function extract(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12*1024*1024)throw new Error('Choose a PNG, JPEG or WebP image under 12 MB.');imageFile=file;imageHash=await S.hashFile(file);if(state.bets.some(b=>b.screenshotHash===imageHash))throw new Error('This screenshot belongs to a recorded bet. Update that wager instead.');if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=URL.createObjectURL(file);const current=Object.fromEntries(new FormData($('#bet-form')));betDialog(current);$('#ocr-status').textContent='Loading local OCR engine…';let worker;try{if(!window.Tesseract)await new Promise((res,rej)=>{const el=document.createElement('script');el.src='https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js';el.onload=res;el.onerror=()=>rej(new Error('OCR library unavailable. Enter the fields manually.'));document.head.append(el);});worker=await window.Tesseract.createWorker('eng',1,{logger:m=>{if($('#ocr-status'))$('#ocr-status').textContent=`${m.status} ${m.progress?Math.round(m.progress*100)+'%':''}`;}});const result=await worker.recognize(file);ocrText=result.data.text;const fields=E.ocrFields(ocrText);betDialog({...current,stake:fields.stake??current.stake,multiplier:fields.multiplier??current.multiplier,potential:fields.potential??current.potential});}catch(e){$('#ocr-status').textContent=e.message;}finally{if(worker)await worker.terminate();}}
function settleDialog(id){const b=state.bets.find(b=>b.id===id);modal('Confirm settlement received',`<p class="hint">${esc(b.legs.map(l=>l.selection).join(' + '))}</p>${b.resolution?`<div class="notice info">Public feed suggests ${money(b.resolution.payout)}. Native ticket rules, fees and actual receipt still need confirmation.</div>`:''}<form id="settle-form" data-id="${id}"><label>Status<select name="status"><option value="won">Won</option><option value="lost">Lost</option><option value="cashed-out">Cashed out · win/loss calculated from payout</option><option value="voided">Voided / adjusted / cancelled</option></select></label><label>Actual gross payout received ($)<input name="payout" type="number" step="0.01" min="0" required value=""></label><label>Optional settlement screenshot<input name="receipt" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="hint">Use the actual received amount. A cancelled leg may settle at its last fair market price; it is not automatically removed from a US combo.</p><label class="check"><input required type="checkbox">I verified the result and this payout has been credited.</label>${errorBox()}<button class="primary full">Confirm received settlement</button></form>`);}
function correctBetDialog(id){const b=state.bets.find(b=>b.id===id);modal('Correct pending ticket',`<p class="hint">Use the accepted ticket values from Polymarket. The previous values remain in the audit trail.</p><form id="correct-bet-form" data-id="${id}"><label>Selected competitors · one per line<textarea name="selections" required rows="${Math.max(3,b.legs.length)}">${esc(b.legs.map(l=>l.selection).join('\n'))}</textarea></label><div class="settings-grid">${numberField('Actual stake ($)','stake',b.stake/100)}${numberField('Accepted multiplier','multiplier',b.multiplier)}${numberField('Potential gross payout ($)','potential',b.potential/100)}<label>Date/time placed · your device timezone<input name="placedAt" type="datetime-local" required value="${new Date(new Date(b.placedAt).getTime()-new Date(b.placedAt).getTimezoneOffset()*60000).toISOString().slice(0,16)}"></label></div><label class="check"><input type="checkbox" required>I checked these corrected values against Polymarket.</label>${errorBox()}<button class="primary full">Save ticket correction</button></form>`);}
async function researchDialog(id){const m=markets.find(m=>m.id===id)||state.combos.flatMap(c=>c.legs).find(m=>m.id===id);if(!m)return;modal('Research & market details','<div class="skeleton"></div>');try{await api.verify([m]);m.research=await research.research(m);modal('Research & market details',researchHTML(m));}catch(e){modal('Research unavailable',`<p>${esc(e.message)}</p>`);}}
function researchHTML(m){const r=m.research;return `<h3>${esc(m.title)}</h3><p class="hint">${esc(m.sportName)} · ${date(m.start)}</p><div class="badge-row"><span class="pill">${esc(m.status)}</span><span class="pill">${m.comboEnabled?'Native leg enabled':'Native eligibility unconfirmed'}</span></div><div class="notice info">Market favorite: ${esc(m.favorite?.name||'Unknown')} · midpoint-implied ${pct(m.favorite?.probability)}.<br>Research-supported lean: unavailable. No independently validated probability model is connected.</div><p class="hint">${esc(r?.summary||'Research not requested.')}</p>${r?.teams?.map(t=>`<div class="research-team"><h3>${esc(t.name)}</h3><p>${t.windows.map(w=>`Last ${w.n}: ${w.count}/${w.n} available, ${w.wins} wins`).join('<br>')}</p><table><thead><tr><th>Date</th><th>Opponent</th><th>Score</th></tr></thead><tbody>${t.events.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.opponent)} ${e.home?'(home)':'(away)'}</td><td>${e.for}–${e.against}</td></tr>`).join('')}</tbody></table><a class="tiny" href="${esc(t.source)}" target="_blank" rel="noopener">TheSportsDB source ↗</a></div>`).join('')||''}<div class="table-scroll"><table><tbody><tr><th>Order-book spread</th><td>${m.spread==null?'Unavailable':(m.spread*100).toFixed(2)+'¢'}</td></tr><tr><th>Resting bid / ask shares</th><td>${m.depth?`${m.depth.bid??'Unknown'} / ${m.depth.ask??'Unknown'}`:'Unavailable'}</td></tr><tr><th>Dollar liquidity</th><td>Not supplied; depth is not dollar liquidity</td></tr><tr><th>Research fetched</th><td>${r?date(r.at):'Not fetched'}</td></tr><tr><th>Book verified</th><td>${m.verifiedAt?date(m.verifiedAt):'Not verified'}</td></tr></tbody></table></div><p class="hint">Buying quotes can sum above 100% because of spread. Complementary midpoints sum to 100% by construction, not as independent confirmation. No raw side-price sum is used.</p><a href="${esc(m.url)}" target="_blank" rel="noopener">View original US market ↗</a>`;}
function findCombo(id){return combos.find(c=>c.id===id)||state.combos.find(c=>c.id===id);}
async function saveCombo(c){if(state.combos.some(x=>x.id===c.id)){toast('Draft already saved.');return;}await mutate(s=>s.combos.push(structuredClone(c)));toast('Draft saved. It is not a wager.');}
function allocateDialog(id){modal('Record a completed contribution',`<p class="hint">Select where the money came from. Only confirm after the real transfer happened.</p><form id="allocate-form" data-id="${id}"><label>Source<select name="source"><option value="incoming">Received crypto payment</option><option value="bankroll">Actual withdrawal from betting bankroll</option></select></label>${numberField('Amount transferred ($)','amount','')}<label class="check"><input required type="checkbox">I completed this transfer into savings.</label>${errorBox()}<button class="primary full">Confirm contribution</button></form>`);}
function splitDialog(id){const b=state.branches.find(b=>b.id===id);modal('Allocate received branch funds',`<p class="hint">${money(b.payout)} received. Money already spent or reserved cannot be allocated again.</p><form id="split-form" data-id="${id}"><label>Child stakes in dollars, separated by commas<input name="stakes" required placeholder="1, 1"></label><label>Maximum tree levels<input name="levels" type="number" min="2" max="50" value="10"></label>${errorBox()}<button class="primary full">Reserve child branches</button></form>`);}
async function showImage(id){const b=state.bets.find(b=>b.id===id);const hash=b.receiptHash||b.screenshotHash;if(hash){const blob=await S.read('images',hash);if(blob){if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=URL.createObjectURL(blob);modal('Private wager screenshot',`<img class="preview-image" style="max-height:65vh" src="${imageUrl}" alt="Recorded wager screenshot"><p class="hint">Stored on this device. Screenshots are excluded from JSON backups and Sheets sync.</p>`);return;}}modal('Attach wager screenshot',`<form id="attach-form" data-id="${id}"><label>Screenshot<input name="image" required type="file" accept="image/png,image/jpeg,image/webp"></label>${errorBox()}<button class="primary full">Attach to existing wager</button></form>`);}
let lastResolutionCheck=0;
async function checkBet(id,quiet=false){const b=state.bets.find(b=>b.id===id);if(!b?.legs.every(l=>l.slug)){if(!quiet)toast('Market IDs are missing. Confirm this wager’s settlement manually.');return;}const r=await api.settlements(b);if(r.estimate){const updated=await S.commit(s=>{const current=s.bets.find(x=>x.id===id);if(current?.status==='pending')current.resolution=r.estimate;},false);state=updated.state;if(!quiet)render();notify('Settlement available','A recorded combo has public results. Confirm its actual received payout.',b.id+'-settled');if(!quiet)toast('Public results found. Confirm the actual received payout.');}else if(!quiet)toast('No complete verifiable settlement yet. Wager remains pending.');}
const notified=new Set();
function notify(title,body,id){if(notified.has(id))return;notified.add(id);if(state.settings.notifications&&'Notification' in window&&Notification.permission==='granted'){navigator.serviceWorker?.ready.then(r=>r.showNotification(title,{body,icon:'./icon-192.png',tag:id})).catch(()=>{});}}
function notifyNewMarkets(){const list=E.filteredMarkets(markets,{...filters,window:'180'});if(list.length)notify('Upcoming US markets',`${list.length} open matches in your next-three-hour window.`,'markets-'+Math.floor(Date.now()/3600000));}
function reminders(){for(const c of state.combos)for(const l of c.legs){if(l.start>Date.now()&&l.start-Date.now()<600000)notify('Saved combo starting soon',l.title+' · '+date(l.start),l.eventId+'-start');}if(!state.incoming.receivedAt&&Date.now()>=Date.parse(state.incoming.due))notify('Expected payment reminder','Check whether your November 5 payment has arrived.','payment-due');const m=E.metrics(state);if(m.deposited&&m.available<state.settings.lowBalance)notify('Low recorded balance',`${money(m.available)} available. Review your ledger.`,'low-'+Math.floor(Date.now()/86400000));const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles'}).format(new Date()),pl=state.bets.filter(b=>b.settledAt&&new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles'}).format(new Date(b.settledAt))===today).reduce((a,b)=>a+b.payout-b.stake,0);if(pl<=-state.settings.dailyLoss)notify('Daily loss reminder',`Recorded daily P/L is ${money(pl)}.`,'loss-'+today);if(Date.now()-lastResolutionCheck>300000){lastResolutionCheck=Date.now();void(async()=>{for(const b of state.bets.filter(b=>b.status==='pending'&&!b.resolution).slice(0,5))await checkBet(b.id,true);})();}}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;try{
 switch(action){
 case'close':dialog.close();break;
 case'go-combos':location.hash='combos';break;case'go-games':location.hash='games';break;
 case'settings':settingsDialog();break;case'deposit':depositDialog();break;case'refresh':await scan();break;
 case'more':showCount+=30;$('#games-list').innerHTML=gameList();break;
 case'target':target=Number(button.dataset.target);combos=[];comboFeedback='';render();break;
 case'generate':await generate();break;
 case'research':await researchDialog(id);break;
 case'combo-research':{const c=findCombo(id);modal('Research each leg',c.legs.map(l=>`<div class="bet-row"><h3>${esc(l.selection)}</h3><p class="hint">${esc(l.research?.summary||'Research unavailable.')}</p><button data-action="research" data-id="${esc(l.id)}">Full details</button></div>`).join(''));break;}
 case'save-combo':await saveCombo(findCombo(id));break;
 case'copy-combo':{const c=findCombo(id);const text=`Edgeboard candidate · Polymarket US\n${c.legs.map((l,i)=>`${i+1}. ${l.selection} — ${l.title} — ${date(l.start)}\n${l.url}`).join('\n')}\nReference ${c.multiplier.toFixed(2)}×, not an accepted native quote.\nSnapshot: ${date(c.at)}. Verify eligibility, current price and payout in Polymarket.`;try{await navigator.clipboard.writeText(text);toast('Candidate copied. Verify the native quote before placing.');}catch{modal('Copy candidate',`<textarea rows="12" readonly>${esc(text)}</textarea>`);}break;}
 case'decline':combos=combos.filter(c=>c.id!==id);render();toast('Candidate declined. No money moved.');break;
 case'log-combo':{const c=findCombo(id);await saveCombo(c);beginBet(c);break;}
 case'upload':case'manual':beginBet();break;
 case'settle':settleDialog(id);break;case'correct-bet':correctBetDialog(id);break;case'check-bet':await checkBet(id);break;case'bet-image':await showImage(id);break;
 case'start-branch':await mutate(s=>E.startBranch(s,100));toast('$1 reserved. Attach a confirmed wager to this branch.');break;
 case'split':splitDialog(id);break;case'release':await mutate(s=>E.cancelBranch(s,id));toast('Reservation released.');break;
 case'receive':modal('Confirm payment received',`<p class="hint">This records the actual external payment; it does not add money to your betting bankroll.</p><form id="receive-form">${numberField('Actual amount received ($)','amount',900)}<label class="check"><input type="checkbox" required>I received this payment.</label>${errorBox()}<button class="primary full">Confirm receipt</button></form>`);break;
 case'allocate':allocateDialog(id);break;
 case'edit-goal':{const g=state.goals.find(g=>g.id===id);modal('Edit savings goal',`<form id="goal-form" data-id="${id}"><label>Goal name<input name="name" required value="${esc(g.name)}"></label>${numberField('Target ($)','target',g.target/100)}${errorBox()}<button class="primary full">Save goal</button></form>`);break;}
 case'wallet-snapshot':{const w=E.latestWalletSnapshot(state);modal('Check against Polymarket',`<p class="hint">Copy the three numbers from the Polymarket account page. This creates a dated checkpoint and never counts a mismatch as profit.</p><form id="wallet-snapshot-form">${numberField('Available cash ($)','available',w?w.available/100:29.49)}${numberField('Open positions value ($)','positions',w?w.positions/100:18.47)}${numberField('Total account value ($)','total',w?w.total/100:47.96)}<label>Date/time checked · your device timezone<input name="at" type="datetime-local" required value="${localDateTime()}"></label><label class="check"><input type="checkbox" required>I copied these values from my Polymarket account.</label>${errorBox()}<button class="primary full">Save wallet checkpoint</button></form>`);break;}
 case'correct-deposit':{const first=state.cash.filter(c=>c.kind==='deposit').sort((a,b)=>a.at.localeCompare(b.at))[0];if(!first)throw new Error('Record your actual initial deposit first.');modal('Correct the initial deposit',`<p class="hint">Currently recorded: ${money(first.amount)}. Enter the amount actually deposited. This edits that original deposit and keeps an audit record; wagers and payouts are preserved.</p><form id="correct-deposit-form">${numberField('Actual initial deposit ($)','amount',first.amount===2500?15:first.amount/100)}${errorBox()}<button class="primary full">Save deposit correction</button></form>`);break;}
 case'sync':if(!state.settings.proxy){settingsDialog();toast('Connect the provided Worker and Apps Script first.');}else{if(!state.outbox.length)await mutate(()=>{});await S.sync(state,updateSync);}break;
 case'export':S.download('edgeboard-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(S.snapshot(state),null,2));toast('Backup exported. Screenshots remain on this device.');break;
 case'csv':S.download('edgeboard-wagers.csv',S.csv(state.bets),'text/csv');break;
 case'import':modal('Restore a JSON backup',`<p class="hint">Restoring replaces this device’s ledger. Export your current records first. API credentials are not imported.</p><form id="import-form"><label>Edgeboard JSON backup<input type="file" name="backup" accept=".json,application/json" required></label><label class="check"><input type="checkbox" required>I exported my current ledger and want to replace it.</label>${errorBox()}<button class="primary full">Validate & restore backup</button></form>`);break;
 case'notifications':if(!('Notification' in window))throw new Error('Notifications are unavailable in this browser. On iPhone, install the PWA first.');if(await Notification.requestPermission()==='granted'){await mutate(s=>s.settings.notifications=true);toast('Open-app notifications enabled.');}break;
 }
 }catch(e){toast(e.message);}
});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(!form.id)return;const data=new FormData(form),v=k=>data.get(k);const submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{
 switch(form.id){
 case'wallet-snapshot-form':await mutate(s=>E.recordWalletSnapshot(s,{available:E.cents(v('available')),positions:E.cents(v('positions')),total:E.cents(v('total')),at:new Date(v('at')).toISOString()}));break;
 case'correct-deposit-form':await mutate(s=>E.correctInitialDeposit(s,E.cents(v('amount'))));break;
 case'correct-bet-form':{const selections=String(v('selections')).split('\n').map(x=>x.trim()).filter(Boolean);await mutate(s=>E.correctPendingBet(s,form.dataset.id,{selections,stake:E.cents(v('stake')),potential:E.cents(v('potential')),multiplier:Number(v('multiplier')),placedAt:new Date(v('placedAt')).toISOString()}));break;}
 case'deposit-form':await mutate(s=>E.deposit(s,E.cents(v('amount'))));break;
 case'settings-form':{const proxy=String(v('proxy')||'').trim().replace(/\/$/,'');if(proxy&&new URL(proxy).protocol!=='https:')throw new Error('Worker URL must use HTTPS.');const lo=Number(v('favmin'))/100,hi=Number(v('favmax'))/100;if(lo>hi)throw new Error('Favorite minimum cannot exceed maximum.');await mutate(s=>{Object.assign(s.settings,{stake:E.cents(v('stake')),riskPercent:Number(v('risk')),dailyLoss:E.cents(v('loss')),lowBalance:E.cents(v('low')),cashoutAt:E.cents(v('cashout')),cashoutAmount:E.cents(v('withdraw')),overallGoal:E.cents(v('overall')),maxPages:Number(v('pages')),proxy});});filters.min=lo;filters.max=hi;if(v('token'))sessionStorage.setItem('edgeboard-sync-token',String(v('token')));api=new MarketAPI(proxy);api.sports=catalog;research=new ResearchAPI(proxy);break;}
 case'bet-form':{const names=String(v('selections')).split('\n').map(x=>x.trim()).filter(Boolean);const legs=names.map((selection,i)=>{const original=draftContext?.legs[i];return original&&original.selection===selection?structuredClone(original):{selection,sport:String(v('sport')||'Unspecified'),sportName:String(v('sport')||'Unspecified')};});const stake=E.cents(v('stake')),potential=E.cents(v('potential')),multiplier=Number(v('multiplier'));if(Math.abs(potential-stake*multiplier)>Math.max(5,potential*.03))throw new Error('Stake, accepted multiplier and potential payout differ by over 3%. Recheck the ticket.');if(imageFile&&imageHash)await S.write('images',imageHash,imageFile);await mutate(s=>E.logBet(s,{ticketId:String(v('ticketId')||'').trim(),stake,potential,multiplier,placedAt:new Date(v('placedAt')).toISOString(),legs,screenshotHash:imageHash,branchId:String(v('branchId')||''),comboId:draftContext?.id||null,target:draftContext?.target||null,source:draftContext?'edgeboard':'manual'}));break;}
 case'settle-form':{const file=v('receipt');let hash=null;if(file?.size){validateImage(file);hash=await S.hashFile(file);if(state.bets.some(b=>b.id!==form.dataset.id&&(b.screenshotHash===hash||b.receiptHash===hash)))throw new Error('This image already belongs to another wager.');await S.write('images',hash,file);}await mutate(s=>{const b=E.settleBet(s,form.dataset.id,String(v('status')),E.cents(v('payout')));if(hash)b.receiptHash=hash;});break;}
 case'attach-form':{const file=v('image');validateImage(file);const hash=await S.hashFile(file);if(state.bets.some(b=>b.id!==form.dataset.id&&(b.screenshotHash===hash||b.receiptHash===hash)))throw new Error('Image already belongs to another wager.');await S.write('images',hash,file);await mutate(s=>s.bets.find(b=>b.id===form.dataset.id).screenshotHash=hash);break;}
 case'split-form':await mutate(s=>E.splitBranch(s,form.dataset.id,String(v('stakes')).split(',').map(x=>E.cents(x.trim())),Number(v('levels'))));break;
 case'receive-form':await mutate(s=>E.receiveIncoming(s,E.cents(v('amount'))));break;
 case'allocate-form':await mutate(s=>E.allocate(s,form.dataset.id,E.cents(v('amount')),String(v('source'))));break;
 case'goal-form':await mutate(s=>{const g=s.goals.find(g=>g.id===form.dataset.id);g.name=String(v('name')).trim();g.target=E.cents(v('target'));});break;
 case'import-form':{const file=v('backup');if(file.size>10000000)throw new Error('Backup exceeds 10 MB.');const incoming=E.validateBackup(JSON.parse(await file.text()));await mutate(s=>{const settings=s.settings,rev=s.revision;Object.assign(s,incoming,{revision:Math.max(rev,incoming.revision||0),outbox:[],syncAt:null});s.settings={...incoming.settings,proxy:settings.proxy,sheetsUrl:''};});break;}
 }
 dialog.close();toast('Saved to your private ledger.');
 }catch(e){if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}
});
function validateImage(file){if(!file?.size||file.size>12*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Use a PNG, JPEG or WebP under 12 MB.');}
let searchTimer;
document.addEventListener('input',event=>{if(event.target.id==='search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{filters.search=event.target.value;combos=[];comboFeedback='';updateMarketViews();},180);}});
document.addEventListener('change',async event=>{try{const el=event.target;if(el.id==='sport'){filters.sport=el.value;showCount=30;combos=[];comboFeedback='';void scan();}if(el.id==='window'){filters.window=el.value;showCount=30;combos=[];comboFeedback='';updateMarketViews();}if(el.id==='include-awaiting'){filters.includeAwaiting=el.checked;combos=[];comboFeedback='';updateMarketViews();}if(el.id==='lopsided'){filters.lopsided=el.checked;combos=[];comboFeedback='';updateMarketViews();}if(el.id==='bet-file'&&el.files[0])await extract(el.files[0]);if(el.id==='staking-mode'&&el.value==='branch')toast('Reserve branch funds below; select a ready branch when confirming the placed wager.');if(el.name==='status'&&el.closest('#settle-form')&&el.value==='lost')el.form.elements.payout.value='0';}catch(e){toast(e.message);}});
window.addEventListener('hashchange',()=>{route=(location.hash||'#home').slice(1);render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('online',()=>{void scan();void S.sync(state,updateSync);});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state){if(Date.now()-lastUpdate>60000)void scan();reminders();}});
async function init(){try{state=await S.load();api=new MarketAPI(state.settings.proxy);research=new ResearchAPI(state.settings.proxy);const cache=await S.read('cache','markets');if(cache){markets=cache.markets||[];catalog=cache.catalog||[];api.sports=catalog;lastUpdate=cache.at||0;loadedSport=cache.sport||null;for(const m of markets)m.verifiedAt=0;}render();void scan();void S.sync(state,updateSync);if('serviceWorker' in navigator){const reg=await navigator.serviceWorker.register('./sw.js').catch(e=>{toast('Offline installation unavailable: '+e.message);return null;});reg?.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('Update ready. Close and reopen the app to use it; your ledger is preserved.');});});}if(window.Telegram?.WebApp){window.Telegram.WebApp.ready();window.Telegram.WebApp.expand();}setInterval(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>{if(el.dataset.live!=='true')el.textContent=countdown(Number(el.dataset.countdown));});if(!document.hidden)reminders();},30000);setInterval(()=>{if(!document.hidden&&!scanning&&!generating)void scan();if(!document.hidden)void S.sync(state,updateSync);},60000);}catch(e){main.innerHTML=heading('Your ledger needs attention.',esc(e.message))+empty('Storage could not be opened.','Use a browser with IndexedDB enabled. Existing data has not been reset.');}}
void init();
